package com.nightbeam.donutshards.event;
import org.bukkit.event.*;import java.util.UUID;
public final class ShardRewardEvent extends Event implements Cancellable {private static final HandlerList HANDLERS=new HandlerList();private final UUID player;private final String reward;private long amount;private boolean cancelled;public ShardRewardEvent(UUID player,String reward,long amount,boolean async){super(async);this.player=player;this.reward=reward;this.amount=amount;}public UUID player(){return player;}public String reward(){return reward;}public long amount(){return amount;}public void amount(long v){amount=v;}public boolean isCancelled(){return cancelled;}public void setCancelled(boolean v){cancelled=v;}public HandlerList getHandlers(){return HANDLERS;}public static HandlerList getHandlerList(){return HANDLERS;}}
